/** The header counter's byte order by sender architecture, as m2ir gives it. */
export const MNDP_HEADER_ORDERS =
	"little-endian on x86_64, arm, arm64; big-endian on mipsbe";

/** The fields MNDP's TLVs are read into, each absent when its TLV is. */
export interface MndpTlvFields {
	/** TLV 1, mac-address. */
	macAddress?: string;
	/** TLV 2, unpack-simple. */
	unpackSimple?: boolean;
	/** TLV 3, unpack-headers. */
	unpackHeaders?: boolean;
	/** TLV 4, unpack-all. */
	unpackAll?: boolean;
	/** TLV 5, identity. */
	identity?: string;
	/** TLV 6, request. */
	requestHex?: string;
	/** TLV 7, version. */
	version?: string;
	/** TLV 8, platform. */
	platform?: string;
	/** TLV 9, aggregated-size. */
	aggregatedSizeHex?: string;
	/** TLV 10, uptime. */
	uptime?: number;
	/** TLV 11, software-id. */
	softwareId?: string;
	/** TLV 12, board. */
	board?: string;
	/** TLV 14, ipv6-enabled. */
	ipv6Enabled?: number;
	/** The name of ipv6Enabled's value. */
	ipv6EnabledName?: string;
	/** TLV 15, address6. */
	address6?: string[];
	/** TLV 16, interface-name. */
	interfaceName?: string;
	/** TLV 17, address4. */
	address4?: string;
	/** TLV 18, running. */
	running?: number;
	/** The names of the bits set in running. */
	runningFlags?: string[];
	/** TLV 19, ttl. */
	ttl?: number;
	/** The name of ttl's value. */
	ttlName?: string;
}

